"""Standalone job scraper for swissre.com (India roles). Generated by the agent; runs with NO LLM calls.
Run:  python scraper.py [output.jsonl]
source_type=html_ssr, pagination=page_number.
"""

import json
import os
import sys
import time
import html as html_lib
from datetime import datetime
from urllib.parse import urljoin, urlparse, urlsplit, urlunsplit, parse_qsl, urlencode

import requests
from bs4 import BeautifulSoup


HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.9",
}

BASE_URL = "https://www.swissre.com/careers/jobSearch.html"
DEFAULT_OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "output.jsonl")


def parse_html(text):
    if isinstance(text, bytes):
        text = text.decode("utf-8", errors="replace")
    text = text or ""
    soup = BeautifulSoup(text, "lxml")
    for tag in ("input", "script", "a"):
        raw_count = text.count("<" + tag)
        if raw_count >= 2 and len(soup.find_all(tag)) < raw_count // 2:
            return BeautifulSoup(text, "html.parser")
    return soup


_INDIA_CITY_FALLBACK = {
    "bengaluru": "Bengaluru", "bangalore": "Bangalore", "mumbai": "Mumbai", "delhi": "Delhi",
    "new delhi": "New Delhi", "gurugram": "Gurugram", "gurgaon": "Gurgaon", "noida": "Noida",
    "hyderabad": "Hyderabad", "chennai": "Chennai", "pune": "Pune", "kolkata": "Kolkata",
    "ahmedabad": "Ahmedabad",
}

def resolve_location(location_raw):
    # returns (city, state, country, country_code) -- all None if unresolvable, never guessed.
    if not location_raw:
        return (None, None, None, None)
    first_segment = location_raw.split(";")[0].strip()  # some platforms join multiple locations with ';'
    parts = [p.strip() for p in first_segment.split(",")]
    if len(parts) >= 2:
        # explicit "City, [State,] Country" format -- last segment is the country
        city = parts[0] or None
        state = parts[1] if len(parts) >= 3 else None
        country_raw = parts[-1]
        if country_raw.lower() in ("india", "in"):
            return (city, state, "India", "IN")
        return (city, state, country_raw or None, None)
    # no comma: bare city name -- only resolve via the small generic fallback dict, never guess otherwise
    bare = first_segment.lower()
    if bare in _INDIA_CITY_FALLBACK:
        return (_INDIA_CITY_FALLBACK[bare], None, "India", "IN")
    return (None, None, None, None)


def collect_job_links(soup, page_url):
    urls = []
    for a in soup.find_all("a", href=True):
        h = a["href"]
        tail = h.rstrip("/").split("/")[-1]
        if any(k in h.lower() for k in ("/job/", "/jobs/", "/position/", "/vacancy/", "/opening/")) \
                or (tail.isdigit() and len(tail) >= 6):
            u = urljoin(page_url, h)
            if u not in urls:
                urls.append(u)
    return urls


def ldjson_objects(soup):
    objs = []
    for tag in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(tag.string or "")
        except (json.JSONDecodeError, TypeError):
            continue
        items = data if isinstance(data, list) else [data]
        for it in items:
            if isinstance(it, dict):
                objs.append(it)
                if isinstance(it.get("@graph"), list):
                    objs.extend(x for x in it["@graph"] if isinstance(x, dict))
    return objs


def ldjson_get(soup, *keys):
    for o in ldjson_objects(soup):
        for k in keys:
            if o.get(k):
                return o[k]
    return None


def ldjson_location(soup):
    for o in ldjson_objects(soup):
        if o.get("@type") == "JobPosting" and o.get("jobLocation"):
            locs = o["jobLocation"] if isinstance(o["jobLocation"], list) else [o["jobLocation"]]
            for l in locs:
                addr = (l or {}).get("address") or {}
                if isinstance(addr, dict) and (addr.get("addressLocality") or addr.get("addressCountry")):
                    city = addr.get("addressLocality") or None
                    state = addr.get("addressRegion") or None
                    country_raw = str(addr.get("addressCountry") or "").strip()
                    if country_raw.upper() in ("IN", "IND", "INDIA"):
                        return (city, state, "India", "IN")
                    return (city, state, country_raw or None, None)
    return None


def find_structural_location(container):
    if container is None:
        return None
    for el in container.find_all(["span", "div", "p", "li", "td", "h1", "h2", "h3"]):
        text = el.get_text(" ", strip=True)
        if not text or len(text) > 100:
            continue
        candidate = text.split(":", 1)[-1].strip() if ":" in text else text
        _, _, country, _ = resolve_location(candidate)
        if country:
            return candidate
    return None


def sel_text(soup, css):
    el = soup.select_one(css)
    return el.get_text(strip=True) if el else None


def parse_date(value):
    if not value:
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
        try:
            dt = datetime.strptime(value, fmt)
            return dt.date().isoformat()
        except Exception:
            pass
    try:
        return datetime.fromisoformat(value).date().isoformat()
    except Exception:
        return None


def fetch_with_retries(url, headers, max_retries=3):
    delay = 1
    last_resp = None
    for attempt in range(max_retries + 1):
        try:
            resp = requests.get(url, headers=headers, timeout=30)
            last_resp = resp
            if resp.status_code < 400:
                return resp
            if resp.status_code in (403, 429) or 500 <= resp.status_code < 600:
                if attempt < max_retries:
                    time.sleep(delay)
                    delay *= 2
                    continue
                return resp
            return resp
        except requests.RequestException:
            if attempt < max_retries:
                time.sleep(delay)
                delay *= 2
                continue
            break
    return last_resp


def normalize_url(u, base=None):
    if not u:
        return None
    return urljoin(base or BASE_URL, u)


def derive_job_id(url):
    if not url:
        return None
    path = urlparse(url).path.rstrip("/")
    parts = path.split("/")
    if parts and parts[-1].isdigit():
        return parts[-1]
    return None


def extract_detail_fields(detail_url, resp_text):
    soup = parse_html(resp_text)
    title = ldjson_get(soup, "headline", "title", "name")
    if isinstance(title, str):
        title = html_lib.unescape(title).strip()
        if " | " in title:
            title = title.split(" | ", 1)[0].strip()
        if title in ("Location:", "Posted:", "Apply now"):
            title = None
    if not title:
        title = sel_text(soup, "h1")
        if title:
            title = html_lib.unescape(title).strip()
            if title in ("Location:", "Posted:", "Apply now"):
                title = None

    job_id = derive_job_id(detail_url)

    loc = ldjson_location(soup)
    if loc is None:
        container = soup
        structural = find_structural_location(container)
        if structural:
            loc = resolve_location(structural)
    if loc is None:
        loc = (None, None, None, None)
    city, state, country, country_code = loc

    date_raw = ldjson_get(soup, "datePublished", "datePosted")
    date_text = html_lib.unescape(date_raw).strip() if isinstance(date_raw, str) and date_raw.strip() else None
    date_posted = parse_date(date_text) if date_text else None

    employment_type = ldjson_get(soup, "employmentType")
    if isinstance(employment_type, list):
        employment_type = ", ".join(str(x) for x in employment_type if x)
    if employment_type:
        employment_type = html_lib.unescape(str(employment_type)).strip()

    work_type = ldjson_get(soup, "workHours")
    if work_type:
        work_type = html_lib.unescape(str(work_type)).strip()

    salary_range = None

    blocks = []
    for el in soup.find_all(["article", "section", "div", "main"]):
        txt = el.get_text(" ", strip=True)
        if not txt:
            continue
        if txt.startswith("Location:"):
            continue
        blocks.append((len(txt), txt))
    job_description = None
    if blocks:
        job_description = html_lib.unescape(max(blocks, key=lambda x: x[0])[1]).strip()

    return {
        "title": title,
        "job_id": job_id,
        "location": {
            "city": city,
            "state": state,
            "country": country,
            "country_code": country_code,
        },
        "url": normalize_url(detail_url),
        "apply_url": None,
        "date_posted": date_posted,
        "date_posted_text": date_text,
        "job_description": job_description,
        "employment_type": employment_type,
        "work_type": work_type,
        "salary_range": salary_range,
    }


def main():
    out_path = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_OUT
    records = []
    seen = set()
    had_error = False

    try:
        resp = fetch_with_retries(BASE_URL, HEADERS)
        if not resp or resp.status_code >= 400:
            print("error: unable to fetch base job search page", file=sys.stderr)
            open(out_path, "w", encoding="utf-8").close()
            sys.exit(1)

        base_soup = parse_html(resp.text)
        all_urls, page_number = [], 1
        prev_links = None
        while page_number <= 120:
            page_url = f"{BASE_URL}{'&' if '?' in BASE_URL else '?'}page={page_number}"
            resp = fetch_with_retries(page_url, HEADERS)
            if not resp or resp.status_code != 200:
                break
            links = collect_job_links(parse_html(resp.text), page_url)
            if prev_links is not None and links == prev_links:
                break
            new_links = [u for u in links if u not in all_urls]
            if not new_links:
                break
            all_urls.extend(new_links)
            prev_links = links
            page_number += 1

        if not all_urls:
            all_urls = collect_job_links(base_soup, BASE_URL)

        for idx, detail_url in enumerate(all_urls):
            if detail_url in seen:
                continue
            seen.add(detail_url)
            try:
                time.sleep(0.35)
                resp = fetch_with_retries(detail_url, HEADERS)
                if not resp:
                    continue
                if resp.status_code == 403:
                    print(f"stderr: skipped blocked detail page {detail_url}", file=sys.stderr)
                    continue
                if resp.status_code >= 400 and not resp.text:
                    continue
                rec = extract_detail_fields(detail_url, resp.text)
                _, _, country, country_code = resolve_location(
                    ", ".join([x for x in [rec["location"]["city"], rec["location"]["state"], rec["location"]["country"]] if x])
                    if any(rec["location"].values()) else None
                )
                if rec["location"]["country_code"] != "IN":
                    continue
                dedupe_key = rec["url"] or rec["job_id"]
                if dedupe_key and dedupe_key in seen:
                    continue
                if dedupe_key:
                    seen.add(dedupe_key)
                records.append(rec)
            except Exception as e:
                had_error = True
                print(f"stderr: failed to process {detail_url}: {e}", file=sys.stderr)
                continue

        with open(out_path, "w", encoding="utf-8") as f:
            for rec in records:
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")

        if had_error:
            sys.exit(1)
        sys.exit(0)

    except Exception as e:
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                for rec in records:
                    f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception:
            pass
        print(f"error: unrecoverable scraper failure: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()